ALTER TABLE "saved_charts" ADD COLUMN "user_id" BIGINT;
CREATE INDEX "index_saved_charts_by_user_id" ON "saved_charts" ("user_id");
CREATE TABLE "users" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "email" TEXT NOT NULL,
    "display_name" TEXT NOT NULL,
    "password_hash" TEXT NOT NULL,
    PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "index_users_by_email" ON "users" ("email");
CREATE TABLE "user_sessions" (
    "token_hash" TEXT NOT NULL,
    "user_id" BIGINT NOT NULL,
    "expires_at" BIGINT NOT NULL,
    PRIMARY KEY ("token_hash")
);
CREATE INDEX "index_user_sessions_by_user_id" ON "user_sessions" ("user_id");
